    ("S", "I", "invoice"),
    ("E", "X", "cancel"),
    ("A", "X", "cancel"),
    ("I", "X", "cancel"),
)


def _numeric_value(value):
    if value is None or value == "":
        return Decimal("0")
    return Decimal(str(value))


def _account_credit_hold(record, tables):
    account_id = record.get("ACCT_ID")
    if account_id is None:
        account_id = ""

    for row in tables.get("ACCT_MASTER", []):
        if row.get("DEL_FLG", "") == "Y":
            continue
        row_account_id = row.get("ACCT_ID")
        if row_account_id is None:
            row_account_id = ""
        if row_account_id == account_id:
            value = row.get("CRED_HOLD", "")
            return "" if value is None else value

    return ""


def fire(state: str, event: str, record: dict, tables: dict) -> dict:
    result_record = dict(record)

    for from_state, to_state, transition_event in _TRANSITIONS:
        if state != from_state or event != transition_event:
            continue

        if from_state == "E" and transition_event == "approve":
            if not (_numeric_value(record.get("TOT_AMT")) > Decimal("0")):
                continue

        if from_state == "A" and transition_event == "cancel":
            if _account_credit_hold(record, tables) == "Y":
                continue

        if from_state == "E" and to_state == "A":
            audits = ["ORD_APPR"]
            notifies = []
        elif from_state == "A" and to_state == "S":
            audits = ["ORD_SHIP"]
            notifies = ["shipped"]
        elif from_state == "S" and to_state == "I":
            audits = ["ORD_INV"]
            notifies = []
        elif from_state == "E" and to_state == "X":
            audits = ["ORD_CANC"]
            notifies = []
        elif from_state == "A" and to_state == "X":
            audits = ["ORD_CANC"]
            notifies = []
        else:
            audits = ["ORD_CANC_INV"]
            notifies = ["credit_note"]

        return {
            "state": to_state,
            "record": result_record,
            "audits": audits,
            "notifies": notifies,
            "matched": True,
        }

    return {
        "state": state,
        "record": result_record,
        "audits": ["WF_NOMATCH"],
        "notifies": [],
        "matched": False,
    }
